// Generated by tackroom from hook __NAME__ in tackroom.yaml; do not edit directly.
// Runs the hook command on __NATIVE_EVENT__ with a Claude Code-style JSON payload
// on stdin. SessionStart additionalContext reaches the model with the next prompt.
import { spawn } from "node:child_process";

const command = __COMMAND__;
const hookEvent = __HOOK_EVENT__;
const timeoutMs = __TIMEOUT_MS__;

function runHook(cwd: string): Promise<string> {
	return new Promise((resolve) => {
		const child = spawn("/bin/sh", ["-c", command], { cwd, stdio: ["pipe", "pipe", "ignore"] });
		let stdout = "";
		const timer = setTimeout(() => child.kill("SIGKILL"), timeoutMs);
		child.stdout.on("data", (chunk) => (stdout += chunk));
		child.on("error", () => {
			clearTimeout(timer);
			resolve("");
		});
		child.on("close", (code) => {
			clearTimeout(timer);
			resolve(code === 0 ? stdout : "");
		});
		child.stdin.on("error", () => {});
		child.stdin.end(JSON.stringify({ hook_event_name: hookEvent, cwd, agent: __AGENT__ }));
	});
}

function additionalContext(stdout: string): string {
	try {
		const context = JSON.parse(stdout)?.hookSpecificOutput?.additionalContext;
		return typeof context === "string" ? context : "";
	} catch {
		return "";
	}
}

export default function (pi: any) {
	let context = "";
	pi.on(__NATIVE_EVENT__, async (_event: unknown, ctx: any) => {
		context = additionalContext(await runHook(ctx?.cwd ?? process.cwd()));
	});
	pi.on("before_agent_start", () => {
		if (!context) return undefined;
		const content = context;
		context = "";
		return { message: { customType: "tackroom-hook", content, display: false } };
	});
}
